import java.util.*;
/** Bounded declarative graphics only; SVG is rendered as an isolated image by the client. */
final class SvgLibraryRules {
 static void require(boolean b,String message){if(!b)throw new IllegalArgumentException(message);}
 static boolean text(Object x,int max){return x instanceof String&&((String)x).length()<=max;}
 static double number(Object x){require(x instanceof Number,"Invalid SVG geometry");double n=((Number)x).doubleValue();require(Double.isFinite(n),"Nonfinite SVG geometry");return n;}
 static Set<String> library(Object input){require(input instanceof List&&((List<?>)input).size()<=64,"Maximum 64 SVG resources");Set<String> ids=new HashSet<>();for(Object entry:(List<?>)input){require(entry instanceof Map,"Invalid SVG resource");Map<?,?> a=(Map<?,?>)entry;require(a.keySet().equals(Set.of("id","title","width","height","states"))&&ids.add(ViewStore.id(a.get("id")))&&text(a.get("title"),128),"Invalid SVG resource fields");for(String key:List.of("width","height")){double n=number(a.get(key));require(n>0&&n<=2000,"SVG native size out of range");}require(a.get("states") instanceof Map,"Invalid SVG states");Map<?,?> states=(Map<?,?>)a.get("states");require(states.containsKey("off")&&Set.of("off","on","fault","unknown","p25","p50","p75").containsAll(states.keySet()),"Invalid SVG states");for(Object svg:states.values())require(text(svg,ViewStore.LIMIT)&&!((String)svg).isEmpty(),"Invalid SVG source");}return ids;}
 static void binding(Object input,boolean bool){require(input instanceof Map,"Invalid SVG binding");Map<?,?> b=(Map<?,?>)input;require(b.keySet().equals(Set.of("path","slot","type"))&&text(b.get("path"),2048)&&text(b.get("slot"),128)&&text(b.get("type"),160),"Invalid SVG binding fields");String path=(String)b.get("path"),slot=(String)b.get("slot"),type=((String)b.get("type")).replace("sys::","");require(!path.isEmpty()&&Arrays.stream(path.split("/",-1)).noneMatch(p->p.isEmpty()||p.equals(".."))&&!slot.isEmpty()&&!slot.equals("meta")&&!slot.matches("(?i).*(password|secret|cred).*|(?i)key"),"Unsafe SVG binding");require(bool?type.equals("bool"):Set.of("float","double","int","short","byte").contains(type),"SVG binding type mismatch");}
 static void objects(Object input,Set<String> assets){require(input instanceof List&&((List<?>)input).size()<=128,"Maximum 128 SVG objects");Set<String> ids=new HashSet<>();Set<String> fields=Set.of("id","assetId","label","x","y","rotation","mode","binding","fault"),required=Set.of("id","assetId","label","x","y","rotation","mode");for(Object item:(List<?>)input){require(item instanceof Map,"Invalid SVG object");Map<?,?> o=(Map<?,?>)item;require(fields.containsAll(o.keySet())&&o.keySet().containsAll(required)&&ids.add(ViewStore.id(o.get("id")))&&assets.contains(o.get("assetId"))&&text(o.get("label"),128)&&Set.of("static","bool","position").contains(o.get("mode")),"Invalid SVG object fields/resource");for(String key:List.of("x","y")){double n=number(o.get(key));require(n>=0&&n<=100,"SVG position out of range");}double angle=number(o.get("rotation"));require(angle==0||angle==90||angle==180||angle==270,"Invalid SVG rotation");boolean staticMode=o.get("mode").equals("static");require(staticMode||o.containsKey("binding"),"Missing SVG state binding");if(o.containsKey("binding"))binding(o.get("binding"),!o.get("mode").equals("position"));if(o.containsKey("fault"))binding(o.get("fault"),true);}}
}
